package ro.leo.visual;
import ro.leo.i18n.L;
import android.content.*;import android.os.Bundle;import android.view.*;import android.widget.*;import java.io.*;import java.util.*;import org.json.*;
public final class ReaderActivity extends LeoActivity {
 private BookDocument book;private File file;private String key;private int chapter,offset,font=18;private boolean night;private ScrollView scroll;private TextView body;private View reading;
 protected void onCreate(Bundle b){super.onCreate(b);String path=getIntent().getStringExtra("file");if(path!=null)load(new File(path));else home();}
 private void home(){list(L.t("Cărți Leo"),Arrays.asList(L.t("Deschide TXT / EPUB"),L.t("Reia ultima carte")),0,new Choice(){public void pick(int i){if(i==0)startActivityForResult(new Intent(ReaderActivity.this,FilesActivity.class).putExtra("pick_book",true),91);else{String last=getSharedPreferences("reader",0).getString("last","");if(last.isEmpty())notice(L.t("Nu există o carte recentă"));else load(new File(last));}}},"",null);}
 static boolean allowed(Context c,File f)throws IOException{if(!f.isFile()||java.nio.file.Files.isSymbolicLink(f.toPath()))return false;for(File root:LeoFileProvider.roots(c).values())if(LeoFileProvider.inside(root,f))return true;return false;}
 private void load(final File f){begin(L.t("Se deschide cartea"));footer("","",L.t("Înapoi"));worker.execute(new Runnable(){public void run(){try{if(!allowed(ReaderActivity.this,f))throw new IOException(L.t("Fișier în afara memoriei disponibile"));final BookDocument loaded=BookDocument.read(f);final String identity=BackupEngine.hash((f.getCanonicalPath()+"|"+f.length()+"|"+f.lastModified()).getBytes("UTF-8"));ui(new Runnable(){public void run(){file=f;book=loaded;key=identity;SharedPreferences p=getSharedPreferences("reader",0);chapter=Math.max(0,Math.min(book.chapters.size()-1,p.getInt(key+"-chapter",0)));offset=Math.max(0,p.getInt(key+"-offset",0));font=Math.max(14,Math.min(26,p.getInt("font",18)));night=p.getBoolean("night",false);p.edit().putString("last",f.getAbsolutePath()).apply();show();}});}catch(final Exception e){ui(new Runnable(){public void run(){notice(L.t("Cartea nu poate fi deschisă: ")+e.getMessage());home();}});}}});}
 private void show(){begin(L.t("Cărți · ")+book.title+" · "+(chapter+1)+"/"+book.chapters.size());reading=root;scroll=new ScrollView(this);body=text(book.chapters.get(chapter),font);if(night){scroll.setBackgroundColor(0xff101219);body.setTextColor(0xffdce4e5);}scroll.addView(body);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));scroll.setFocusable(true);scroll.requestFocus();final ScrollView target=scroll;final TextView text=body;final int at=Math.min(offset,body.length());body.post(new Runnable(){public void run(){if(scroll!=target||body!=text)return;android.text.Layout layout=text.getLayout();if(layout!=null)target.scrollTo(0,layout.getLineTop(layout.getLineForOffset(at)));}});left=new Runnable(){public void run(){capture();menu();}};back=new Runnable(){public void run(){capture();save();finish();}};footer(L.t("Opțiuni"),"← / → capitol",L.t("Înapoi"));}
 private void capture(){if(root!=reading||body==null||body.getLayout()==null)return;android.text.Layout l=body.getLayout();offset=l.getLineStart(l.getLineForVertical(scroll.getScrollY()));}
 private void save(){if(key!=null)getSharedPreferences("reader",0).edit().putInt(key+"-chapter",chapter).putInt(key+"-offset",offset).putInt("font",font).putBoolean("night",night).apply();}
 private void menu(){options(L.t("Lectură"),new String[]{L.t("Capitole"),L.t("Adaugă semn de carte · 0"),L.t("Semne de carte · 5"),L.t("Text mai mare · #"),L.t("Text mai mic · *"),night?L.t("Mod luminos"):L.t("Mod noapte"),L.t("Altă carte")},new Choice(){public void pick(int i){if(i==0){list(L.t("Capitole"),book.names,chapter,new Choice(){public void pick(int n){chapter=n;offset=0;show();}},L.t("Înapoi"),new Runnable(){public void run(){show();}});back=new Runnable(){public void run(){show();}};}else if(i==1)bookmark();else if(i==2)marks();else if(i==3||i==4){font=Math.max(14,Math.min(26,font+(i==3?1:-1)));save();show();}else if(i==5){night=!night;save();show();}else{save();home();}}});}
 private JSONArray bookmarks(){try{return new JSONArray(getSharedPreferences("reader",0).getString(key+"-marks","[]"));}catch(Exception e){return new JSONArray();}}
 private void bookmark(){capture();JSONArray all=bookmarks();for(int i=0;i<all.length();i++){JSONObject mark=all.optJSONObject(i);if(mark!=null&&mark.optInt("chapter")==chapter&&mark.optInt("offset")==offset){notice(L.t("Există deja un semn aici"));return;}}if(all.length()>=12){notice(L.t("Maximum 12 semne · elimină unul din listă"));return;}try{all.put(new JSONObject().put("chapter",chapter).put("offset",offset));getSharedPreferences("reader",0).edit().putString(key+"-marks",all.toString()).apply();notice(L.t("Semn de carte salvat"));}catch(Exception e){notice(L.t("Semn nesalvat"));}}
 private void marks(){final JSONArray all=bookmarks();ArrayList<String> labels=new ArrayList<String>();for(int i=0;i<all.length();i++){JSONObject m=all.optJSONObject(i);labels.add(m==null?L.t("Semn invalid"):L.t("Capitol ")+(m.optInt("chapter")+1)+L.t(" · caracter ")+m.optInt("offset"));}list(L.t("Semne de carte"),labels,0,new Choice(){public void pick(final int n){options(labels.get(n),new String[]{L.t("Deschide"),L.t("Șterge semnul")},new Choice(){public void pick(int action){if(action==0){JSONObject m=all.optJSONObject(n);if(m!=null){chapter=Math.max(0,Math.min(book.chapters.size()-1,m.optInt("chapter")));offset=Math.max(0,m.optInt("offset"));show();}}else{all.remove(n);getSharedPreferences("reader",0).edit().putString(key+"-marks",all.toString()).apply();marks();}}});}},L.t("Înapoi"),new Runnable(){public void run(){show();}});back=new Runnable(){public void run(){show();}};}
 public boolean onKeyDown(int code,KeyEvent e){if(root==reading&&book!=null){if(code==21||code==22||code==KeyEvent.KEYCODE_4||code==KeyEvent.KEYCODE_6){if(e.getRepeatCount()==0){capture();chapter=CircularNavigation.step(chapter,code==21||code==KeyEvent.KEYCODE_4?-1:1,book.chapters.size());offset=0;save();show();}return true;}if(code==KeyEvent.KEYCODE_0||code==KeyEvent.KEYCODE_5){if(e.getRepeatCount()==0){capture();if(code==KeyEvent.KEYCODE_0)bookmark();else marks();}return true;}if(code==KeyEvent.KEYCODE_STAR||code==KeyEvent.KEYCODE_POUND){if(e.getRepeatCount()==0){capture();font=Math.max(14,Math.min(26,font+(code==KeyEvent.KEYCODE_POUND?1:-1)));save();show();}return true;}}return super.onKeyDown(code,e);}
 protected void onPause(){capture();save();super.onPause();}
 protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request==91&&result==RESULT_OK&&data!=null)load(new File(data.getStringExtra("file")));}
}
